package com.abhi.ganasuno.ui

import android.app.Activity
import android.widget.EditText
import android.widget.Toast
import com.abhi.ganasuno.data.*
import com.google.android.material.dialog.MaterialAlertDialogBuilder
import java.util.concurrent.Executor

class Batch28Tools(private val a:Activity,private val io:Executor,private val current:()->Song?,private val saveAudio:(String)->Unit,private val saveVideo:()->Unit){
    private fun toast(t:String)=Toast.makeText(a,t,Toast.LENGTH_LONG).show()
    private fun choose(t:String,rows:List<String>,action:(Int)->Unit){if(rows.isEmpty()){toast("Nothing to show");return};if(t=="Preferred direct-file bitrate" && SmartSettingIndicators.show(MaterialAlertDialogBuilder(a),a,t,rows,listOf(64,128,192,256,320,1411).indexOf(SmartOffline.target(a)),action))return;MaterialAlertDialogBuilder(a).setTitle(t).setItems(rows.toTypedArray()){_,i->action(i)}.setNegativeButton("Close",null).show()}
    private fun ask(t:String,initial:String="",hint:String="",action:(String)->Unit){val e=EditText(a).apply{setText(initial);this.hint=hint;isSaveEnabled=false;maxLines=8};MaterialAlertDialogBuilder(a).setTitle(t).setView(e).setNegativeButton("Cancel",null).setPositiveButton("Continue"){_,_->val raw=e.text.toString();e.text.clear();runCatching{action(raw)}.onFailure{toast(it.message?:"Invalid input")}}.show()}
    private fun info(t:String,text:String){MaterialAlertDialogBuilder(a).setTitle(t).setMessage(text).setPositiveButton("Close",null).show()}
    fun show(){choose("Batch 28 · Offline automation and release alerts",listOf("Register authorized source for current song","Registered sources · save or forget","Download quality · ${SmartOffline.target(a)} kbps","Favourite auto-download · ${if(SmartOffline.auto(a))"On" else "Off"}","Daily smart downloads · ${if(SmartOffline.smart(a))"On" else "Off"}","Automatic download status","Followed artist release alerts","Signing identity check","Last.fm scrobbling (Full)","Authorized video download")){i->when(i){
        0->{val s=current();if(s==null)toast("Play a track first")else register(s)}
        1->registered()
        2->choose("Preferred direct-file bitrate",listOf("64 kbps","128 kbps","192 kbps","256 kbps","320 kbps","Lossless-sized 1411 kbps")){n->SmartOffline.setTarget(a,listOf(64,128,192,256,320,1411)[n]);toast("Preference saved · nearest offered variant, no transcoding")}
        3->configure(true)
        4->configure(false)
        5->info("Automatic downloads",SmartOffline.status(a)+"\n\nUnmetered Wi-Fi only; up to five new files per job. Automatic runs stop at the storage threshold; files are never deleted automatically.")
        6->releaseMenu()
        7->identity()
        8->lastFm()
        9->saveVideo()
    }}}
    private fun register(s:Song){val existing=SmartOffline.variants(a,s.id).joinToString("\n"){"${it.kbps} ${it.url}"};MaterialAlertDialogBuilder(a).setTitle("Authorized audio variants · ${s.title}").setMessage("Only register direct files you own or may download and store. Each line contains declared bitrate then HTTPS URL. Saved URLs are private app data; do not use URLs containing secrets. No streaming-service links, no transcoding.").setNegativeButton("Cancel",null).setPositiveButton("Continue"){_,_->ask("Bitrate and direct URL per line",existing,"128 https://example.org/song.mp3"){raw->SmartOffline.register(a,s.id,Batch28.parse(raw));toast("Authorized variants registered")}}.show()}
    private fun registered(){val ids=SmartOffline.registered(a).sorted();val tracks=(LibraryStore.list("favorites")+LibraryStore.list("local")+LibraryStore.history().map{it.song}+listOfNotNull(current())).associateBy{it.id};choose("Registered authorized sources",ids.map{tracks[it]?.title?:it}){n->val id=ids[n];choose(tracks[id]?.title?:"Authorized source",listOf("Save at preferred quality","Forget registration (keeps downloaded audio)")){i->if(i==0)saveAudio(id)else{SmartOffline.forget(a,id);toast("Registration removed")}}}}
    private fun configure(favorites:Boolean){val active=if(favorites)SmartOffline.auto(a)else SmartOffline.smart(a);MaterialAlertDialogBuilder(a).setTitle(if(active)"Disable automation?" else "Enable automatic authorized downloads?").setMessage(if(active)"Existing saved files are retained." else "Only manually registered authorized variants are eligible. Uses unmetered Wi-Fi and Android background scheduling; at most five files per run. No auto-delete.").setNegativeButton("Cancel",null).setPositiveButton(if(active)"Disable" else "Enable"){_,_->runCatching{SmartOffline.configure(a,if(favorites)!active else SmartOffline.auto(a),if(favorites)SmartOffline.smart(a)else !active)}.onSuccess{toast("Download automation updated")}.onFailure{toast("Could not schedule automation")}}.show()}
    private fun releaseMenu(){choose("Followed artist release alerts",listOf("Set maintainer email for MusicBrainz","Find artist and enable alerts","Manage watched artists","Check now")){n->when(n){
        0->ask("Maintainer email · sent to MusicBrainz",ArtistReleaseWatch.contact(a)){raw->ArtistReleaseWatch.contact(a,raw);toast("Contact saved")}
        1->{val contact=ArtistReleaseWatch.contact(a);if(contact.isBlank())toast("Set maintainer email first")else ask("Search artist") { q->task({MusicCatalogue.search(contact,"artist",q,20)}){rows->choose("Confirm artist identity",rows.map{listOf(it.title,it.note,it.type).filter{v->v.isNotBlank()}.joinToString(" · ")}){i->val artist=rows[i];runCatching{ArtistReleaseWatch.watch(a,artist.id,artist.title)}.onSuccess{toast("Following artist · first successful check sets baseline")}.onFailure{toast(it.message?:"Could not follow artist")}}}}}
        2->{val rows=ArtistReleaseWatch.watched(a).toList();choose("Watched artists",rows.map{it.second}){i->MaterialAlertDialogBuilder(a).setTitle("Stop alerts for ${rows[i].second}?").setMessage("This removes the release watch but keeps the local artist follow.").setNegativeButton("Cancel",null).setPositiveButton("Stop alerts"){_,_->ArtistReleaseWatch.unwatch(a,rows[i].first);toast("Alerts stopped")}.show()}}
        3->task({ArtistReleaseWatch.run(a){!Thread.currentThread().isInterrupted}}){fail->toast("Release check finished · $fail failed artist requests")}
    }}}
    private fun <T> task(run:()->T,done:(T)->Unit){toast("Checking metadata…");io.execute{val r=runCatching(run);a.runOnUiThread{if(!a.isDestroyed&&!a.isFinishing)r.onSuccess(done).onFailure{toast("Metadata request failed")}}}}
    private fun identity(){choose("Signing identity",listOf("View and compare installed certificate","Set trusted reference SHA-256","Clear trusted reference")){n->when(n){0->runCatching{BuildIdentity.report(a)}.onSuccess{info("Build signing identity",it)}.onFailure{toast("Signing identity unavailable")};1->ask("Independent trusted certificate SHA-256 (comma-separated)"){raw->BuildIdentity.setExpected(a,raw);info("Signing comparison",BuildIdentity.report(a))};2->{BuildIdentity.clear(a);toast("Trusted reference cleared")}}}}
    private fun lastFm(){if(!LastFmScrobble.available()){toast("Available in Full edition only");return};choose("Last.fm · ${LastFmScrobble.status()}",listOf("Enable for this session","Disconnect","View submission status")){n->when(n){0->MaterialAlertDialogBuilder(a).setTitle("Share eligible listening activity with Last.fm?").setMessage("If enabled, track name, artist, album, duration and start time are sent to Last.fm after sufficient playback. Only the current app process; no credentials are saved. Requires your own API key, secret and authorized session key. No retroactive history upload or automatic retry.").setNegativeButton("Cancel",null).setPositiveButton("Continue"){_,_->secret("Last.fm API key"){key->secret("Last.fm API secret"){apiSecret->secret("Authorized Last.fm session key"){sk->runCatching{LastFmScrobble.configure(key,apiSecret,sk)}.onSuccess{toast("Last.fm enabled")}.onFailure{toast(it.message?:"Invalid credentials")}}}}}.show();1->{LastFmScrobble.disconnect();toast("Disconnected")};2->info("Last.fm",LastFmScrobble.status())}}}
    private fun secret(title:String,action:(String)->Unit){val e=EditText(a).apply{isSaveEnabled=false;setSingleLine(true);inputType=android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD};MaterialAlertDialogBuilder(a).setTitle(title).setView(e).setNegativeButton("Cancel"){_,_->e.text.clear()}.setPositiveButton("Continue"){_,_->val value=e.text.toString().trim();e.text.clear();action(value)}.show()}
}
